export function evaluate({ inputs, time }) {
 const u = inputs.launchSpeed, g = inputs.gravity;
 const T = u / g, H = u * u / (2 * g);
 const t = Math.min(Math.max(time, 0), 2 * T);
 const yT = u * t - g * t * t / 2;
 const vT = u - g * t;
 const rel = t >= T;
 const tau = Math.max(t - T, 0);
 const yD = rel ? H - g * tau * tau / 2 : H;
 const vD = rel ? -g * tau : 0;
 const aD = rel ? -g : 0;
 const aT = -g;
 const sT = t < 1e-9 ? 'At launch' : (t > 2 * T - 1e-9 ? 'At launch height' : (Math.abs(t - T) < 1e-6 ? 'At the top' : (t < T ? 'Rising' : 'Falling')));
 const sD = t >= 2 * T - 1e-9 ? 'At launch height' : (!rel ? 'Held in place' : (tau < 0.15 ? 'Just released' : 'Falling together'));
 const gy = 360, sc = 270 / 2.2;
 const py = y => gy - y * sc;
 const o = [];
 o.push(...sdk.panel({ id: 'lane.toss', x: 10, y: 40, w: 305, h: 360, title: 'Toss', state: sT }));
 o.push(...sdk.panel({ id: 'lane.drop', x: 325, y: 40, w: 305, h: 360, title: 'Drop', state: sD }));
 const xs = [{ n: 'toss', x: 140, y: yT, v: vT, a: aT }, { n: 'drop', x: 455, y: yD, v: vD, a: aD }];
 o.push(sdk.groundMark('mark.toss', 160, gy + 14, 200, 'launch'));
 o.push(sdk.groundMark('mark.drop', 475, gy + 14, 200, 'launch'));
 o.push(sdk.gate('gate.drop', 455, py(H) + 22, { open: rel, label: 'gate' }));
 for (const b of xs) {
  const cy = py(b.y);
  o.push(sdk.circle('ball.' + b.n, b.x, cy, 28, {}));
  o.push(...sdk.vector('vec.v.' + b.n, { x: b.x - 30, y: cy }, { value: b.v, direction: 'up' }, { scale: 14, label: 'v' }));
  o.push(...sdk.vector('vec.a.' + b.n, { x: b.x + 30, y: cy }, { value: b.a, direction: 'up' }, { scale: 5, label: 'a' }));
  o.push(...sdk.callout(b.x + 60, cy - 20, ['v ' + sdk.format(b.v, 2) + ' m/s', 'a ' + sdk.format(b.a, 1) + ' m/s^2'], { id: 'callout.' + b.n }));
 }
 return {
  frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'tossedVelocity', value: vT }, { id: 'tossedAcceleration', value: aT }, { id: 'dropVelocity', value: vD }, { id: 'dropAcceleration', value: aD }] },
  quantities: { launchSpeed: u, gravity: g, apexTime: T, apexHeight: H, tossedVelocity: vT, tossedAcceleration: aT, tossedHeight: yT, dropVelocity: vD, dropAcceleration: aD, dropHeight: yD }
 };
}
